    let route = String::from("DN-07");
    let parcels: u32 = 300;
    let total = parcels;           // (A)
    let n = ship(route);           // (B)
    println!("{parcels} {total}"); // (C)
    println!("{n}");               // (D)
    println!("{route}");           // (E)
}

